'use strict';
let expandedCaseId='',warehouseExpanded=true,caseSectionExpanded=true;
const caseStatuses=['尚未開始','執行中','結案'];
function caseClass(status){return status==='執行中'?'running':status==='結案'?'closed':'';}
function caseDate(value){return value||'未填寫';}
function caseRows(){
 const cases=state.cases||[];
 if(!cases.length)return '<div class="empty">尚未建立案件</div>';
 return cases.map(c=>'<details class="case-item" data-case="'+esc(c.id)+'" '+(expandedCaseId===c.id?'open':'')+'><summary class="case-summary"><span class="case-name"><strong>'+esc(c.name)+'</strong><small>'+esc(c.vendor||'未填廠商')+'</small></span><span class="case-status '+caseClass(c.status)+'">'+esc(c.status)+'</span></summary><div class="case-detail"><div class="case-fields"><div class="case-field"><span>案件名稱</span><strong>'+esc(c.name)+'</strong></div><div class="case-field"><span>案件廠商</span><strong>'+esc(c.vendor||'未填寫')+'</strong></div><div class="case-field"><span>接案日期</span><strong>'+esc(caseDate(c.acceptedDate))+'</strong></div><div class="case-field"><span>結案日期</span><strong>'+esc(caseDate(c.closedDate))+'</strong></div></div><div class="case-actions">'+caseStatuses.map(s=>'<button type="button" class="small '+(c.status===s?'selected':'')+'" data-case-status="'+esc(c.id)+'" data-status="'+esc(s)+'">'+esc(s)+'</button>').join('')+'<button type="button" class="small" data-case-edit="'+esc(c.id)+'">修改案件資料</button></div></div></details>').join('');
}
function enhanceCases(){
 const main=$('main'),demo=$('.demo'),heading=$('.heading'),workspace=$('.workspace'),footer=$('.footer-note');if(!main||!demo||!heading||!workspace||main.querySelector('.case-workspace'))return;
 state.cases??=[];
 const cases=document.createElement('details');cases.className='workspace case-workspace case-fold';cases.open=caseSectionExpanded;cases.innerHTML='<summary><span>'+esc(siteText('casesTitle'))+'</span></summary><div class="case-head"><small>'+esc(siteText('casesDescription'))+'</small><button type="button" id="new-case" class="primary">＋ 建立專案</button></div><div class="case-list">'+caseRows()+'</div>';demo.after(cases);cases.ontoggle=()=>{caseSectionExpanded=cases.open;};
 const fold=document.createElement('details');fold.className='warehouse-fold';fold.open=warehouseExpanded;fold.innerHTML='<summary>'+esc(siteText('heading'))+'</summary>';heading.before(fold);heading.querySelector('h1')?.remove();fold.append(heading,workspace,footer);
 fold.ontoggle=()=>{warehouseExpanded=fold.open;};
 $('#new-case').onclick=()=>editCase();
 document.querySelectorAll('.case-item').forEach(el=>el.ontoggle=()=>{if(el.open)expandedCaseId=el.dataset.case;else if(expandedCaseId===el.dataset.case)expandedCaseId='';});
 document.querySelectorAll('[data-case-edit]').forEach(el=>el.onclick=e=>{e.preventDefault();editCase(el.dataset.caseEdit);});
 document.querySelectorAll('[data-case-status]').forEach(el=>el.onclick=e=>{e.preventDefault();const c=state.cases.find(x=>x.id===el.dataset.caseStatus);if(!c||c.status===el.dataset.status)return;c.status=el.dataset.status;if(c.status==='結案'&&!c.closedDate)c.closedDate=new Date().toISOString().slice(0,10);addAudit('更新案件狀態',c.name+' → '+c.status,'案件管理 > '+c.name);expandedCaseId=c.id;persist();render();toast('案件狀態已更新');});
}
function editCase(id,fromAdmin=false){
 const existing=(state.cases||[]).find(c=>c.id===id),c=existing||{id:crypto.randomUUID(),name:'',vendor:'',acceptedDate:'',closedDate:'',status:'尚未開始'};
 modal(existing?'修改案件資料':'建立專案',field('案件名稱','name',c.name,'required maxlength="100"')+field('案件廠商','vendor',c.vendor,'maxlength="100"')+'<div class="form-grid">'+field('接案日期','acceptedDate',c.acceptedDate,'type="date"')+field('結案日期','closedDate',c.closedDate,'type="date"')+'</div><label class="field">案件狀態<select name="status">'+caseStatuses.map(s=>'<option '+(c.status===s?'selected':'')+'>'+s+'</option>').join('')+'</select></label>','儲存案件',fd=>{const name=String(fd.get('name')||'').trim();if(!name)error('請填寫案件名稱。');const next={...c,name,vendor:String(fd.get('vendor')||'').trim(),acceptedDate:String(fd.get('acceptedDate')||''),closedDate:String(fd.get('closedDate')||''),status:String(fd.get('status'))};if(next.closedDate&&next.acceptedDate&&next.closedDate<next.acceptedDate)error('結案日期不可早於接案日期。');if(next.status==='結案'&&!next.closedDate)next.closedDate=new Date().toISOString().slice(0,10);if(existing)Object.assign(existing,next);else{state.cases??=[];state.cases.unshift(next);}addAudit(existing?'修改管理案件項目':'新增管理案件項目',next.name,'案件管理 > '+next.name);expandedCaseId=next.id;persist();if(fromAdmin){$('#modal').close();renderAdmin();toast(existing?'案件資料已更新':'案件已建立');}else done(existing?'案件資料已更新':'案件已建立');});
}
const renderBeforeCases=render;render=function(){renderBeforeCases();enhanceCases();};
function enhanceAdminCases(){const main=$('main');if(!main||$('#admin-cases'))return;const cards=main.querySelectorAll('.admin-card'),card=document.createElement('section');card.id='admin-cases';card.className='admin-card';card.innerHTML='<h2>'+esc(siteText('casesTitle'))+'</h2><p>可在後台建立、修改或刪除所有案件資料。</p>'+(state.cases||[]).map(c=>'<div class="admin-row"><strong>'+esc(c.name)+'</strong><span>'+esc(c.vendor||'未填廠商')+' · '+esc(c.status)+'</span><button type="button" data-admin-case="'+esc(c.id)+'">修改</button><button type="button" class="danger-button" data-admin-case-delete="'+esc(c.id)+'">刪除</button></div>').join('')+'<div class="admin-actions"><button type="button" id="admin-new-case">＋ 建立專案</button></div>';if(cards[0])cards[0].after(card);else main.append(card);$('#admin-new-case').onclick=()=>editCase(undefined,true);document.querySelectorAll('[data-admin-case]').forEach(el=>el.onclick=()=>editCase(el.dataset.adminCase,true));document.querySelectorAll('[data-admin-case-delete]').forEach(el=>el.onclick=()=>{const index=state.cases.findIndex(c=>c.id===el.dataset.adminCaseDelete);if(index<0||!confirm('確定刪除案件「'+state.cases[index].name+'」？'))return;const removed=state.cases.splice(index,1)[0];addAudit('刪除管理案件項目',removed.name,'案件管理 > '+removed.name);persist();renderAdmin();toast('案件已刪除');});}
const renderAdminBeforeCases=renderAdmin;renderAdmin=function(){renderAdminBeforeCases();enhanceAdminCases();};
